  builder_.add_UNCERTAINTY_SOURCE(UNCERTAINTY_SOURCE);
  builder_.add_HAS_MAHALANOBIS_SQUARED(HAS_MAHALANOBIS_SQUARED);
  builder_.add_HAS_MAXIMUM_PROBABILITY(HAS_MAXIMUM_PROBABILITY);
