  static ::flatbuffers::Offset<CQRLaunchClosure> Pack(::flatbuffers::FlatBufferBuilder &_fbb, const CQRLaunchClosureT* _o, const ::flatbuffers::rehasher_function_t *_rehasher = nullptr);
