inline ::flatbuffers::Offset<CQR> CreateCQR(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    ::flatbuffers::Offset<CQRPairRequest> PAIR_REQUEST = 0,
    ::flatbuffers::Offset<CQRCatalogRequest> CATALOG_REQUEST = 0,
    ::flatbuffers::Offset<CQRProbabilityRequest> PROBABILITY_REQUEST = 0,
    ::flatbuffers::Offset<CQRProbabilityResult> PROBABILITY_RESULT = 0,
    ::flatbuffers::Offset<CQRAlfanoRequest> ALFANO_REQUEST = 0,
    ::flatbuffers::Offset<CQRAlfanoResult> ALFANO_RESULT = 0,
    ::flatbuffers::Offset<CQREvent> EVENT_RESULT = 0,
    ::flatbuffers::Offset<TIMInstant> TCA_RESULT = 0,
    ::flatbuffers::Offset<CQRCatalogResult> CATALOG_RESULT = 0,
    ::flatbuffers::Offset<CQRNativeDocument> NATIVE_DOCUMENT = 0,
    ::flatbuffers::Offset<CQRIndexRequest> INDEX_REQUEST = 0,
    ::flatbuffers::Offset<CQRIndexResult> INDEX_RESULT = 0,
    ::flatbuffers::Offset<CQRWindowRequest> WINDOW_REQUEST = 0,
    ::flatbuffers::Offset<CQRDestroyRequest> DESTROY_REQUEST = 0,
    bool VERSION_QUERY = false,
    ::flatbuffers::Offset<CQRVersionResult> VERSION_RESULT = 0,
    ::flatbuffers::Offset<CQRLaunchRequest> LAUNCH_REQUEST = 0,
    ::flatbuffers::Offset<CQRLaunchResult> LAUNCH_RESULT = 0) {
  CQRBuilder builder_(_fbb);
  builder_.add_LAUNCH_RESULT(LAUNCH_RESULT);
  builder_.add_LAUNCH_REQUEST(LAUNCH_REQUEST);
  builder_.add_VERSION_RESULT(VERSION_RESULT);
  builder_.add_DESTROY_REQUEST(DESTROY_REQUEST);
  builder_.add_WINDOW_REQUEST(WINDOW_REQUEST);
  builder_.add_INDEX_RESULT(INDEX_RESULT);
  builder_.add_INDEX_REQUEST(INDEX_REQUEST);
  builder_.add_NATIVE_DOCUMENT(NATIVE_DOCUMENT);
  builder_.add_CATALOG_RESULT(CATALOG_RESULT);
  builder_.add_TCA_RESULT(TCA_RESULT);
  builder_.add_EVENT_RESULT(EVENT_RESULT);
  builder_.add_ALFANO_RESULT(ALFANO_RESULT);
  builder_.add_ALFANO_REQUEST(ALFANO_REQUEST);
  builder_.add_PROBABILITY_RESULT(PROBABILITY_RESULT);
  builder_.add_PROBABILITY_REQUEST(PROBABILITY_REQUEST);
  builder_.add_CATALOG_REQUEST(CATALOG_REQUEST);
  builder_.add_PAIR_REQUEST(PAIR_REQUEST);
  builder_.add_VERSION_QUERY(VERSION_QUERY);
  return builder_.Finish();
}

